class Solution {
public:
    int minMoves(vector<vector<int>>& rooks) {
        int n = rooks.size();
        vector<int> rows, cols;
        for (auto& p : rooks) { rows.push_back(p[0]); cols.push_back(p[1]); }
        sort(rows.begin(), rows.end());
        sort(cols.begin(), cols.end());
        int ans = 0;
        for (int i = 0; i < n; ++i) ans += abs(rows[i] - i) + abs(cols[i] - i);
        return ans;
    }
};
